+/** Records the identity and outcome of a request that changes data. */
+export function recordAudit(store, entry) {
+  store.data.audit.push({ ...entry });
+}
+
+/** Lists audit entries newest first, including ties in reverse insertion order. */
+export function listAudit(store) {
+  return [...store.data.audit].reverse().sort((a, b) => b.time.localeCompare(a.time));
+}
