@@ -0,0 +1,20 @@
+import { AppError } from "../errors.js";
+
+const cookPaths = [
+  /^\/recipes\/[^/]+\/cook$/,
+  /^\/batches\/[^/]+\/waste$/,
+  /^\/temperatures$/,
+  /^\/stocktakes\/[^/]+\/counts$/,
+];
+
+/** Authenticates the bearer key and checks its role for this request. */
+export function authorize(store, headers, method, path) {
+  const authorization = Object.entries(headers).find(([name]) => name.toLowerCase() === "authorization")?.[1];
+  const token = typeof authorization === "string" ? /^Bearer ([^\s]+)$/i.exec(authorization)?.[1] : null;
+  const key = token ? store.data.apiKeys.find((entry) => entry.key === token) : null;
+  if (!key) throw new AppError("unauthorized");
+  if (key.role === "manager") return key;
+  if ((key.role === "viewer" || key.role === "cook") && method === "GET" && path !== "/audit") return key;
+  if (key.role === "cook" && method === "POST" && cookPaths.some((pattern) => pattern.test(path))) return key;
+  throw new AppError("forbidden");
+}
