@@ -0,0 +1,102 @@
+import test from "node:test";
+import assert from "node:assert/strict";
+import { mkdtempSync, writeFileSync, rmSync } from "node:fs";
+import { tmpdir } from "node:os";
+import { join } from "node:path";
+import { createApp } from "../src/http/server.js";
+import { openStore } from "../src/db/store.js";
+import { migrate } from "../src/db/migrations.js";
+import { fresh, seed, NOW } from "./helpers.js";
+
+const headers = (role) => ({ Authorization: `Bearer seed-${role}` });
+
+test("every route requires a recognized bearer key", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const authorization of [undefined, "Bearer unknown", "seed-manager", "Bearer", "Bearer seed-manager extra"]) {
+    const response = await handle({ path: "/items", headers: { authorization } });
+    assert.equal(response.status, 401);
+    assert.equal(response.body.error.code, "unauthorized");
+    assert.equal(typeof response.body.error.message, "string");
+  }
+  assert.equal((await handle({ path: "/nope" })).status, 401);
+  assert.deepEqual(store.data.audit, []);
+});
+
+test("viewers read but cannot write; only managers can read audit", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  for (const role of ["viewer", "cook", "manager"]) {
+    assert.equal((await handle({ path: "/items", headers: headers(role) })).status, 200);
+    const audit = await handle({ path: "/audit", headers: headers(role) });
+    assert.equal(audit.status, role === "manager" ? 200 : 403);
+    if (role !== "manager") assert.equal(audit.body.error.code, "forbidden");
+  }
+  const before = structuredClone(store.data);
+  const response = await handle({ method: "POST", path: "/recipes/1/cook", headers: headers("viewer"), body: { portions: 4 } });
+  assert.equal(response.status, 403);
+  assert.deepEqual(store.data, before);
+});
+
+test("cooks can perform the four kitchen writes, but cannot manage data", async () => {
+  const store = fresh();
+  const handle = createApp(store);
+  const request = (method, path, body, role = "cook") => handle({ method, path, body, headers: headers(role) });
+  assert.equal((await request("POST", "/stocktakes", { location: "dry" }, "manager")).status, 201);
+  for (const [path, body] of [
+    ["/recipes/1/cook", { portions: 4 }],
+    ["/batches/1/waste", { qty: 0.1 }],
+    ["/temperatures", { location: "fridge", celsius: 3 }],
+    ["/stocktakes/1/counts", { batchId: 1, counted: 2 }],
+  ]) assert.ok((await request("POST", path, body)).status < 300, path);
+  for (const [method, path] of [
+    ["POST", "/orders"], ["POST", "/stocktakes"], ["POST", "/stocktakes/1/finish"],
+    ["PUT", "/items/1/allergens"], ["POST", "/prices"], ["POST", "/dishes"],
+    ["POST", "/jobs/nightly"], ["POST", "/import/items"], ["POST", "/outbox/1/sent"],
+  ]) assert.equal((await request(method, path, {})).status, 403, path);
+  assert.equal(store.data.audit.length, 5);
+});
+
+test("audit persists with each write and lists newest first without exposing keys", async () => {
+  const dir = mkdtempSync(join(tmpdir(), "larder-auth-"));
+  try {
+    const file = join(dir, "db.json");
+    writeFileSync(file, JSON.stringify(seed()));
+    const store = openStore(file);
+    let saves = 0;
+    const save = store.save.bind(store);
+    store.save = () => { saves++; save(); };
+    const handle = createApp(store, { clock: () => NOW });
+    for (const celsius of [3, 4]) {
+      const result = await handle({ method: "POST", path: `/temperatures?reading=${celsius}`, headers: headers("cook"), body: { location: "fridge", celsius } });
+      assert.equal(result.status, 201);
+    }
+    assert.equal(saves, 2);
+    const failed = await handle({ method: "POST", path: "/temperatures", headers: headers("cook"), body: {} });
+    assert.equal(failed.status, 400);
+    const reopened = openStore(file);
+    const response = await createApp(reopened)({ path: "/audit", headers: headers("manager") });
+    assert.deepEqual(response.body, [4, 3].map((reading) => ({
+      time: new Date(NOW).toISOString(), keyName: "Seed cook", method: "POST",
+      path: `/temperatures?reading=${reading}`, status: 201,
+    })));
+    assert.equal(saves, 2);
+    assert.equal(reopened.data.temperatures.length, 4);
+  } finally {
+    rmSync(dir, { recursive: true, force: true });
+  }
+});
+
+test("schema 2 migration adds empty access collections and preserves existing records", () => {
+  const data = { ...seed(), schemaVersion: 2 };
+  delete data.apiKeys;
+  delete data.audit;
+  const migrated = migrate(data);
+  assert.deepEqual(migrated.apiKeys, []);
+  assert.deepEqual(migrated.audit, []);
+  assert.deepEqual(migrated.items, data.items);
